        broker
            .scaffold_shell_app_value(
                confirmed_scaffold_input(
                    &broker,
                    &shell.id,
                    "Widget staging",
                    "widget test",
                    "dom",
                )
                .await,
            )
            .await
            .expect("scaffold");
        let layout = broker.layout(&shell.id).expect("layout");
        let workspace = layout.root().join(layout.workspace_rel());
        let path = "app/mcp-widget/package.json";
